# -*- coding: utf-8 -*-
"""为校准挑选候选页：扫每本书的页，算文字量 / 图块 / 色彩饱和度 / 覆盖度，
输出 JSON 供人工挑 10 张"答案已知"的图版页。

用法：python pick_calib.py [--step 4] [--out calib_candidates.json]
只用 pymupdf，不动网络。
"""
from __future__ import annotations

import argparse
import json
import math
import sys
from pathlib import Path

import pymupdf as fitz

BOOK_DIR = Path(r"E:\03-Book\Photography")
WATERMARK = (
    "annas-archive", "anna's archive", "anna\u2019s archive", "document generated by",
    "pdffactory", "z-library", "1lib.sk", "z-lib", "duxu", "本文件由",
)


def real_text(page) -> str:
    t = page.get_text("text") or ""
    lines = []
    for ln in t.splitlines():
        low = ln.lower()
        if any(w in low for w in WATERMARK):
            continue
        lines.append(ln)
    return "\n".join(lines).strip()


def page_stats(page, thumb_w=240):
    txt = real_text(page)
    imgs = page.get_images(full=True)
    pix = page.get_pixmap(matrix=fitz.Matrix(thumb_w / page.rect.width, thumb_w / page.rect.width),
                          colorspace=fitz.csRGB, alpha=False)
    samp = pix.samples
    n = pix.width * pix.height
    sat_sum = 0.0
    colored = 0
    lum_sum = 0.0
    step = 4 * 7  # 每个像素 3 字节（RGB），每 7 像素取 1
    cnt = 0
    for i in range(0, n * 3 - 3, step):
        r, g, b = samp[i], samp[i + 1], samp[i + 2]
        mx, mn = max(r, g, b), min(r, g, b)
        sat_sum += (mx - mn) / mx if mx else 0.0
        if (mx - mn) > 40:
            colored += 1
        lum_sum += 0.299 * r + 0.587 * g + 0.114 * b
        cnt += 1
    cnt = max(cnt, 1)
    return {
        "page": page.number + 1,
        "chars": len(txt),
        "imgs": len(imgs),
        "sat": round(sat_sum / cnt, 3),
        "colored": round(colored / cnt, 3),
        "lum": round(lum_sum / cnt, 1),
    }


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--step", type=int, default=4, help="每 N 页取一个样本")
    ap.add_argument("--out", default="calib_candidates.json")
    args = ap.parse_args()

    out = {}
    for pdf in sorted(BOOK_DIR.glob("*.pdf")):
        try:
            doc = fitz.open(pdf)
        except Exception as e:  # noqa: BLE001
            print(f"SKIP {pdf.name}: {e}", file=sys.stderr)
            continue
        rows = []
        pages = doc.page_count
        idxs = list(range(0, pages, max(1, args.step)))
        if idxs[-1] != pages - 1:
            idxs.append(pages - 1)
        for i in idxs:
            try:
                rows.append(page_stats(doc[i]))
            except Exception:  # noqa: BLE001
                continue
        doc.close()
        rows.sort(key=lambda r: (-r["colored"], r["chars"]))
        out[pdf.name] = {"pages": pages, "samples": len(rows), "top": rows[:14]}
        print(f"OK {pdf.name[:36]:38s} pages={pages:4d} samples={len(rows):3d} "
              f"best_color={rows[0]['colored']:.2f}")

    dest = Path(__file__).resolve().parent.parent / args.out
    dest.write_text(json.dumps(out, ensure_ascii=False, indent=1), encoding="utf-8")
    print(f"WROTE {dest}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
